#include "onnx/inference_engine.h"
#include <iostream>
#include <sstream>
#include <algorithm>
#include <chrono>
#include <cstring>

// ONNX Runtime C++ API (header-only wrapper)
#include <onnxruntime_cxx_api.h>

// Embedded model symbols (generated by xxd -i)
// When EMBED_MODEL is enabled, model_embedded.c provides these
#ifdef EMBED_MODEL
extern "C" {
    extern const unsigned char model_onnx[];
    extern const unsigned int model_onnx_len;
}
#endif

namespace llmzip {

// ============================================================================
// PIMPL implementation details
// ============================================================================
struct InferenceEngine::Impl {
    Ort::Env env{nullptr};
    Ort::SessionOptions session_options{nullptr};
    std::unique_ptr<Ort::Session> session{nullptr};
    Ort::MemoryInfo memory_info{nullptr};

    std::string model_path;
    int64_t vocab_size = 32128;   // T5 default
    int64_t max_seq_len = 512;
    bool session_loaded = false;

    // Input/output names (populated after session creation)
    std::vector<const char*> input_names;
    std::vector<const char*> output_names;
    std::vector<Ort::AllocatedStringPtr> input_names_ptrs;
    std::vector<Ort::AllocatedStringPtr> output_names_ptrs;

    ~Impl() {
        session.reset();
    }

    // Minimal BPE-like tokenization for T5 (UTF-8 aware, space-prefix based)
    // This is a simplified tokenizer — in production, use HuggingFace tokenizers
    std::vector<int64_t> tokenize(const std::string& input) {
        std::vector<int64_t> tokens;
        tokens.push_back(0); // T5: <pad> or </s> as start

        std::string word;
        std::istringstream stream(input);
        while (stream >> word) {
            // T5 uses SentencePiece: "word" → "▁word"
            // We simulate with subword splitting for common tokens
            bool matched = false;
            // Check for known abbreviations (uppercase combos)
            if (word.size() >= 2 && word.size() <= 8 &&
                std::all_of(word.begin(), word.end(), [](char c) {
                    return std::isupper(c) || c == ':' || c == '_' || c == '-';
                })) {
                // Treat as single token
                tokens.push_back(hash_to_token_id(word));
                matched = true;
            }
            if (!matched) {
                // Split into character/subword chunks
                for (size_t i = 0; i < word.size(); ) {
                    // Try to match 3, 2, 1 char subwords
                    int matched_len = 0;
                    for (int len = 3; len >= 1 && matched_len == 0; --len) {
                        if (i + len <= word.size()) {
                            std::string sub = word.substr(i, len);
                            int64_t id = hash_to_token_id(sub);
                            if (id > 0) {
                                tokens.push_back(id);
                                matched_len = len;
                            }
                        }
                    }
                    if (matched_len == 0) {
                        tokens.push_back(static_cast<int64_t>(static_cast<unsigned char>(word[i]) + 100));
                        matched_len = 1;
                    }
                    i += matched_len;
                }
            }
            // Add space token between words
            if (tokens.size() < max_seq_len - 1)
                tokens.push_back(3); // space/sep token
        }

        // Truncate
        if (tokens.size() > max_seq_len)
            tokens.resize(max_seq_len);
        // Pad with pad_id (0)
        tokens.resize(max_seq_len, 0);

        return tokens;
    }

    // Simple hash-based token ID mapping for demo
    // In production, use a proper tokenizer model
    int64_t hash_to_token_id(const std::string& token) {
        // Deterministic hash to vocab range [10, vocab_size-1]
        uint64_t h = 14695981039346656037ULL;
        for (char c : token) {
            h ^= static_cast<unsigned char>(c);
            h *= 1099511628211ULL;
        }
        return 10 + static_cast<int64_t>(h % (vocab_size - 20));
    }

    std::string detokenize(const std::vector<int64_t>& tokens) {
        std::string result;
        for (int64_t id : tokens) {
            if (id <= 0 || id == 1) continue; // skip pad/eos
            if (id == 3) { result += ' '; continue; } // space
            result += "[" + std::to_string(id) + "]";
        }
        return result;
    }
};

// ============================================================================
// InferenceEngine public API
// ============================================================================
InferenceEngine::InferenceEngine()
    : pimpl_(std::make_unique<Impl>()) {
}

InferenceEngine::~InferenceEngine() = default;

// ---------------------------------------------------------------------------
// initialize_embedded — load model from linker-embedded binary
// ---------------------------------------------------------------------------
bool InferenceEngine::initialize_embedded() {
#ifdef EMBED_MODEL
    try {
        const size_t model_size = model_onnx_len;
        if (model_size == 0) {
            std::cerr << "[InferenceEngine] Embedded model is empty\n";
            initialized_ = false;
            return false;
        }

        pimpl_->env = Ort::Env(ORT_LOGGING_LEVEL_WARNING, "llmzip-embedded");
        pimpl_->session_options = Ort::SessionOptions();
        pimpl_->session_options.SetIntraOpNumThreads(2);
        pimpl_->session_options.SetGraphOptimizationLevel(GraphOptimizationLevel::ORT_ENABLE_ALL);

        // Load model from memory buffer
        pimpl_->session = std::make_unique<Ort::Session>(
            pimpl_->env,
            model_onnx,
            model_size,
            pimpl_->session_options);
        pimpl_->model_path = "[embedded]";
        pimpl_->session_loaded = true;

        // Query input/output names
        Ort::AllocatorWithDefaultOptions allocator;
        size_t num_inputs = pimpl_->session->GetInputCount();
        for (size_t i = 0; i < num_inputs; ++i) {
            auto name = pimpl_->session->GetInputNameAllocated(i, allocator);
            pimpl_->input_names_ptrs.push_back(std::move(name));
            pimpl_->input_names.push_back(pimpl_->input_names_ptrs.back().get());
        }
        size_t num_outputs = pimpl_->session->GetOutputCount();
        for (size_t i = 0; i < num_outputs; ++i) {
            auto name = pimpl_->session->GetOutputNameAllocated(i, allocator);
            pimpl_->output_names_ptrs.push_back(std::move(name));
            pimpl_->output_names.push_back(pimpl_->output_names_ptrs.back().get());
        }

        pimpl_->memory_info = Ort::MemoryInfo::CreateCpu(OrtArenaAllocator, OrtMemTypeDefault);

        initialized_ = true;
        std::cout << "[InferenceEngine] Loaded embedded model (" << (model_size / 1048576) << " MB)\n";

        // Debug: print input info
        std::cerr << "[InferenceEngine] Model inputs:\n";
        for (size_t i = 0; i < pimpl_->input_names.size(); ++i) {
            auto type_info = pimpl_->session->GetInputTypeInfo(i);
            auto tensor_info = type_info.GetTensorTypeAndShapeInfo();
            auto shape = tensor_info.GetShape();
            std::string type_str;
            auto elem = tensor_info.GetElementType();
            if (elem == ONNX_TENSOR_ELEMENT_DATA_TYPE_FLOAT) type_str = "float32";
            else if (elem == ONNX_TENSOR_ELEMENT_DATA_TYPE_INT64) type_str = "int64";
            else if (elem == ONNX_TENSOR_ELEMENT_DATA_TYPE_INT32) type_str = "int32";
            else type_str = "type=" + std::to_string(elem);
            std::cerr << "  [" << i << "] " << pimpl_->input_names[i] << " : " << type_str << " shape=[";
            for (size_t d = 0; d < shape.size(); ++d) {
                if (d > 0) std::cerr << ",";
                if (shape[d] < 0) std::cerr << "?";
                else std::cerr << shape[d];
            }
            std::cerr << "]\n";
        }
        std::cerr << "[InferenceEngine] Model outputs:\n";
        for (size_t i = 0; i < pimpl_->output_names.size(); ++i) {
            auto type_info = pimpl_->session->GetOutputTypeInfo(i);
            auto tensor_info = type_info.GetTensorTypeAndShapeInfo();
            auto shape = tensor_info.GetShape();
            std::cerr << "  [" << i << "] " << pimpl_->output_names[i] << " shape=[";
            for (size_t d = 0; d < shape.size(); ++d) {
                if (d > 0) std::cerr << ",";
                if (shape[d] < 0) std::cerr << "?";
                else std::cerr << shape[d];
            }
            std::cerr << "]\n";
        }

        return true;
    } catch (const Ort::Exception& e) {
        std::cerr << "[InferenceEngine] Embedded model init error: " << e.what() << std::endl;
        initialized_ = false;
        return false;
    }
#else
    std::cerr << "[InferenceEngine] Model not embedded (compile with -DEMBED_MODEL=ON)\n";
    initialized_ = false;
    return false;
#endif
}

// ---------------------------------------------------------------------------
// initialize — load model from file, or from embedded binary if path is empty
// ---------------------------------------------------------------------------
bool InferenceEngine::initialize(const std::string& model_path) {
    // If no path given, try embedded model first
    if (model_path.empty()) {
        return initialize_embedded();
    }

    try {
        pimpl_->env = Ort::Env(ORT_LOGGING_LEVEL_WARNING, "llmzip");
        pimpl_->session_options = Ort::SessionOptions();

        // Optimizations
        pimpl_->session_options.SetIntraOpNumThreads(2);
        pimpl_->session_options.SetGraphOptimizationLevel(GraphOptimizationLevel::ORT_ENABLE_ALL);

        // Load model from file
        pimpl_->session = std::make_unique<Ort::Session>(
            pimpl_->env, model_path.c_str(), pimpl_->session_options);
        pimpl_->model_path = model_path;
        pimpl_->session_loaded = true;

        // Query input/output names
        Ort::AllocatorWithDefaultOptions allocator;
        size_t num_inputs = pimpl_->session->GetInputCount();
        for (size_t i = 0; i < num_inputs; ++i) {
            auto name = pimpl_->session->GetInputNameAllocated(i, allocator);
            pimpl_->input_names_ptrs.push_back(std::move(name));
            pimpl_->input_names.push_back(pimpl_->input_names_ptrs.back().get());
        }
        size_t num_outputs = pimpl_->session->GetOutputCount();
        for (size_t i = 0; i < num_outputs; ++i) {
            auto name = pimpl_->session->GetOutputNameAllocated(i, allocator);
            pimpl_->output_names_ptrs.push_back(std::move(name));
            pimpl_->output_names.push_back(pimpl_->output_names_ptrs.back().get());
        }

        // Memory info
        pimpl_->memory_info = Ort::MemoryInfo::CreateCpu(OrtArenaAllocator, OrtMemTypeDefault);

        initialized_ = true;
        return true;
    } catch (const Ort::Exception& e) {
        std::cerr << "[InferenceEngine] ONNX init error: " << e.what() << std::endl;
        initialized_ = false;
        return false;
    }
}

// ---------------------------------------------------------------------------
// compress_text — run fused T5 encoder-decoder in one shot
// ---------------------------------------------------------------------------
InferenceResult InferenceEngine::compress_text(const std::string& input) {
    InferenceResult result;
    result.success = false;

    if (!initialized_) {
        result.error_message = "Engine not initialized";
        return result;
    }

    try {
        auto start = std::chrono::steady_clock::now();

        // 1. Tokenize input
        std::vector<int64_t> input_ids = pimpl_->tokenize(input);
        std::vector<int64_t> attention_mask(pimpl_->max_seq_len, 1);
        std::vector<int64_t> input_shape = {1, pimpl_->max_seq_len};

        // 2. Determine output info index (last output = logits)
        size_t logits_output_idx = pimpl_->output_names.size() - 1;

        // 3. Set up decoder input (start with pad token)
        const int64_t pad_token_id = 0;
        const int64_t eos_token_id = 1;
        std::vector<int64_t> decoder_ids = {pad_token_id};

        Ort::Value decoder_input_tensor = Ort::Value::CreateTensor<int64_t>(
            pimpl_->memory_info, decoder_ids.data(), decoder_ids.size(),
            std::vector<int64_t>{1, 1}.data(), 2);

        Ort::Value decoder_mask_tensor = Ort::Value::CreateTensor<int64_t>(
            pimpl_->memory_info, attention_mask.data(), attention_mask.size(),
            input_shape.data(), input_shape.size());

        // 4. Build full input list (fused T5 expects: input_ids, attention_mask, decoder_input_ids, encoder_hidden_states?)
        std::vector<Ort::Value> ort_inputs;
        std::vector<const char*> input_names;

        // We need to match the model's expected inputs
        // From the error we know: input_ids, attention_mask are fed
        // encoder_hidden_states is missing — the model expects it
        // decoder_input_ids may also be expected

        // Detect what the model wants
        bool has_encoder_hidden_input = false;
        bool has_decoder_input_ids = false;
        bool has_attention_mask = false;

        for (const auto& name : pimpl_->input_names) {
            std::string n(name);
            if (n == "encoder_hidden_states") has_encoder_hidden_input = true;
            else if (n == "decoder_input_ids") has_decoder_input_ids = true;
            else if (n == "attention_mask") has_attention_mask = true;
        }

        // Build decoder hidden states placeholder (if needed)
        // Shape: [1, seq_len, d_model] — we don't know exact dims, use 768 (T5-base) or 512 (T5-small)
        const int64_t d_model = 512; // T5-small hidden size
        std::vector<int64_t> hidden_shape = {1, (int64_t)pimpl_->max_seq_len, d_model};
        size_t hidden_elems = 1 * pimpl_->max_seq_len * d_model;
        // Model expects int64 despite type info saying float32 (quantization quirk)
        std::vector<int64_t> dummy_hidden(hidden_elems, 0);
        Ort::Value hidden_tensor = Ort::Value::CreateTensor<int64_t>(
            pimpl_->memory_info, dummy_hidden.data(), dummy_hidden.size(),
            hidden_shape.data(), hidden_shape.size());

        for (size_t i = 0; i < pimpl_->input_names.size(); ++i) {
            const std::string& name = pimpl_->input_names[i];
            input_names.push_back(pimpl_->input_names[i]);

            if (name == "input_ids") {
                ort_inputs.push_back(std::move(
                    Ort::Value::CreateTensor<int64_t>(
                        pimpl_->memory_info, input_ids.data(), input_ids.size(),
                        input_shape.data(), input_shape.size())));
            } else if (name == "attention_mask") {
                ort_inputs.push_back(std::move(
                    Ort::Value::CreateTensor<int64_t>(
                        pimpl_->memory_info, attention_mask.data(), attention_mask.size(),
                        input_shape.data(), input_shape.size())));
            } else if (name == "decoder_input_ids") {
                ort_inputs.push_back(std::move(decoder_input_tensor));
            } else if (name == "encoder_hidden_states") {
                // Provide dummy — the fused graph will compute actual values
                ort_inputs.push_back(std::move(hidden_tensor));
            } else {
                // Unknown input — provide dummy float tensor
                std::vector<float> dummy(1, 0.0f);
                ort_inputs.push_back(std::move(
                    Ort::Value::CreateTensor<float>(
                        pimpl_->memory_info, dummy.data(), dummy.size(),
                        std::vector<int64_t>{1, 1}.data(), 2)));
            }
        }

        // 5. Run full graph once
        std::vector<const char*> output_names;
        for (size_t i = 0; i < pimpl_->output_names.size(); ++i)
            output_names.push_back(pimpl_->output_names[i]);

        if (ort_inputs.empty() || output_names.empty()) {
            result.error_message = "No valid inputs/outputs for model";
            result.output_text = input;
            return result;
        }

        auto output_tensors = pimpl_->session->Run(
            Ort::RunOptions{nullptr},
            input_names.data(), ort_inputs.data(), ort_inputs.size(),
            output_names.data(), output_names.size());

        // 6. Extract logits from last output
        std::string compressed;
        if (!output_tensors.empty()) {
            size_t out_idx = std::min(logits_output_idx, output_tensors.size() - 1);

            // Check type: if float32 → logits, if int64 → token IDs
            auto type_info = output_tensors[out_idx].GetTensorTypeAndShapeInfo();
            auto elem_type = type_info.GetElementType();
            auto shape = type_info.GetShape();

            if (elem_type == ONNX_TENSOR_ELEMENT_DATA_TYPE_FLOAT) {
                // Logits output — argmax
                auto* logits = output_tensors[out_idx].GetTensorMutableData<float>();
                size_t total = type_info.GetElementCount();

                if (shape.size() >= 2 && total > 0) {
                    int64_t seq = shape[shape.size() - 2];
                    int64_t voc = shape[shape.size() - 1];
                    std::vector<int64_t> gen_ids;

                    for (int64_t s = 0; s < seq; ++s) {
                        int64_t start = s * voc;
                        int64_t best = 0;
                        float bestv = logits[start];
                        for (int64_t v = 1; v < voc && v < 50000; ++v) {
                            if (logits[start + v] > bestv) {
                                bestv = logits[start + v];
                                best = v;
                            }
                        }
                        if (best == eos_token_id || best == pad_token_id) break;
                        gen_ids.push_back(best);
                    }

                    if (!gen_ids.empty()) {
                        compressed = pimpl_->detokenize(gen_ids);
                        if (compressed.find('[') != std::string::npos) {
                            std::ostringstream oss;
                            for (auto id : gen_ids) {
                                if (oss.tellp() > 0) oss << ' ';
                                oss << id;
                            }
                            compressed = oss.str();
                        }
                        std::cerr << "[T5] Generated " << gen_ids.size()
                                  << " tokens from logits\n";
                    }
                }
            } else if (elem_type == ONNX_TENSOR_ELEMENT_DATA_TYPE_INT64) {
                // Token ID output — use directly
                auto* ids = output_tensors[out_idx].GetTensorMutableData<int64_t>();
                size_t total = type_info.GetElementCount();
                std::vector<int64_t> gen_ids(ids, ids + total);
                compressed = pimpl_->detokenize(gen_ids);
            }
        }

        // 7. Fallback
        if (compressed.empty() || compressed.find('[') != std::string::npos) {
            compressed = input;
            result.confidence_score = 0.0f;
        } else {
            result.confidence_score = 0.85f;
        }

        result.output_text = compressed;
        result.success = true;

        auto end = std::chrono::steady_clock::now();
        result.inference_time_ms = std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count();

    } catch (const Ort::Exception& e) {
        result.error_message = "ONNX inference error: " + std::string(e.what());
        result.output_text = input;
        result.confidence_score = 0.0f;
    }

    return result;
}

InferenceResult InferenceEngine::decompress_text(const std::vector<uint8_t>& compressed_data) {
    InferenceResult result;
    result.success = false;

    if (!initialized_) {
        result.error_message = "Engine not initialized";
        return result;
    }

    try {
        auto start = std::chrono::steady_clock::now();

        // Convert binary data to string of token IDs
        std::string input_str(reinterpret_cast<const char*>(compressed_data.data()),
                               compressed_data.size());

        // Tokenize as-is (assuming already tokenized)
        std::vector<int64_t> input_ids = pimpl_->tokenize(input_str);
        std::vector<int64_t> attention_mask(pimpl_->max_seq_len, 1);

        std::vector<int64_t> input_shape = {1, pimpl_->max_seq_len};
        Ort::Value input_tensor = Ort::Value::CreateTensor<int64_t>(
            pimpl_->memory_info, input_ids.data(), input_ids.size(),
            input_shape.data(), input_shape.size());

        Ort::Value mask_tensor = Ort::Value::CreateTensor<int64_t>(
            pimpl_->memory_info, attention_mask.data(), attention_mask.size(),
            input_shape.data(), input_shape.size());

        std::vector<Ort::Value> ort_inputs;
        ort_inputs.push_back(std::move(input_tensor));
        if (pimpl_->input_names.size() > 1)
            ort_inputs.push_back(std::move(mask_tensor));

        auto output_tensors = pimpl_->session->Run(
            Ort::RunOptions{nullptr},
            pimpl_->input_names.data(), ort_inputs.data(), ort_inputs.size(),
            pimpl_->output_names.data(), pimpl_->output_names.size());

        if (!output_tensors.empty()) {
            auto* output_data = output_tensors[0].GetTensorMutableData<int64_t>();
            size_t output_len = output_tensors[0].GetTensorTypeAndShapeInfo().GetElementCount();

            std::vector<int64_t> output_ids(output_data, output_data + output_len);
            result.output_text = pimpl_->detokenize(output_ids);
            if (result.output_text.empty())
                result.output_text = input_str; // fallback

            result.success = true;
        }

        auto end = std::chrono::steady_clock::now();
        result.inference_time_ms = std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count();

    } catch (const Ort::Exception& e) {
        result.error_message = "ONNX decompress error: " + std::string(e.what());
        result.output_text = "(decompress fallback)";
    }

    return result;
}

std::string InferenceEngine::get_model_info() const {
    if (!initialized_)
        return "Not initialized";
    std::ostringstream oss;
    oss << "Model: " << pimpl_->model_path << "\n";
    oss << "Inputs: " << pimpl_->input_names.size() << "\n";
    for (const auto& name : pimpl_->input_names)
        oss << "  - " << name << "\n";
    oss << "Outputs: " << pimpl_->output_names.size() << "\n";
    for (const auto& name : pimpl_->output_names)
        oss << "  - " << name << "\n";
    oss << "Vocab: " << pimpl_->vocab_size << "\n";
    oss << "Max seq: " << pimpl_->max_seq_len;
    return oss.str();
}

std::vector<int64_t> InferenceEngine::tokenize_input(const std::string& input) {
    return pimpl_->tokenize(input);
}

std::string InferenceEngine::detokenize_output(const std::vector<int64_t>& tokens) {
    return pimpl_->detokenize(tokens);
}

} // namespace llmzip